package com.cipherwell.notezero.ui.pdf

import androidx.test.ext.junit.runners.AndroidJUnit4
import androidx.test.platform.app.InstrumentationRegistry
import kotlinx.coroutines.runBlocking
import org.junit.Assert.assertNotNull
import org.junit.Assert.assertTrue
import org.junit.Test
import org.junit.runner.RunWith

/**
 * Real-platform validation of the note→PDF exporter: the generated bytes must be accepted by
 * `android.graphics.pdf.PdfRenderer` (which is what every PDF viewer uses) and must render the
 * expected pages. Robolectric cannot run PdfDocument/PdfRenderer natively, hence androidTest.
 */
@RunWith(AndroidJUnit4::class)
class NotePdfRenderInstrumentedTest {

    private val context = InstrumentationRegistry.getInstrumentation().targetContext

    private val sample = buildString {
        appendLine("# Project plan")
        appendLine()
        appendLine("Intro with **bold**, *italic*, `code` and ~~strike~~ and [a link](https://example.com).")
        appendLine()
        repeat(30) { index ->
            appendLine("## Section $index")
            appendLine("- first item $index")
            appendLine("- second item")
            appendLine("  1. nested numbered")
            appendLine()
            appendLine("- [x] done $index")
            appendLine("- [ ] todo")
            appendLine()
            appendLine("> quoted line $index")
            appendLine()
            appendLine("| key | value |")
            appendLine("|---|---|")
            appendLine("| a | $index |")
            appendLine()
            appendLine("```kotlin")
            appendLine("fun main() = println(\"page $index\")")
            appendLine("```")
            appendLine()
        }
    }

    @Test
    fun fullDocumentRendersToAPlatformAcceptedPdf() = runBlocking {
        val bytes = NotePdfRenderer().render(sample)
        assertNotNull("renderer must produce bytes", bytes)
        assertTrue("PDF header", String(bytes!!, Charsets.ISO_8859_1).startsWith("%PDF-"))

        val pages = AndroidPdfPageRenderer().render(context, bytes)
        assertTrue("expected a multi-page document, got ${pages.totalPages}", pages.totalPages >= 2)
        assertTrue("platform renderer must produce page bitmaps", pages.bitmaps.isNotEmpty())
        val first = pages.bitmaps.first()
        assertTrue("rendered page must have real pixels", first.width > 100 && first.height > 100)
        pages.bitmaps.forEach { it.recycle() }
    }

    @Test
    fun emptyNoteIsAValidOnePagePdf() = runBlocking {
        val bytes = NotePdfRenderer().render("")
        assertNotNull(bytes)
        val pages = AndroidPdfPageRenderer().render(context, bytes!!)
        assertTrue("empty note should be one page", pages.totalPages == 1)
        pages.bitmaps.forEach { it.recycle() }
    }

    @Test
    fun hostileInputEitherRendersOrFailsCleanlyButNeverThrows() {
        val inputs = listOf(
            "a".repeat(200_000),
            "**".repeat(20_000),
            "| a |".repeat(5_000),
            "\u0000\uD800" + "x".repeat(100),
        )
        inputs.forEach { input ->
            val bytes = NotePdfRenderer().render(input)
            assertNotNull("hostile-but-drawable input should still render", bytes)
            assertTrue(String(bytes!!, Charsets.ISO_8859_1).startsWith("%PDF-"))
        }
    }
}
